unsigned short signal_manager::get_id( const stringx& name ) const
{
  signal_id_map_t::const_iterator i = signal_id_map.find( name );
  if ( i == signal_id_map.end() )
    error( "signal " + name + " not found" );
  return (*i).second;
}
